provider_code.code:
"""
Lattice Echo Memory Provider

A layered, self-curating memory system with four cooperating strata:
1. Working memory: task-local constraints, data points, findings, and step trace
2. Episodic memory: compact records of past task attempts and outcomes
3. Semantic memory: reusable strategic insights and decision criteria
4. Procedural memory: reusable operational techniques, triggers, and pitfalls

Innovations:
- Hierarchical memory strata with different retention and retrieval roles
- Adaptive priority scoring with recency decay, usage, success, failure, and confidence
- LLM-mediated retrieval and synthesis with conflict/uncertainty notes
- LLM-mediated working-set curation rather than keyword matching
- Outcome-aware reinforcement: used memories gain success or failure evidence
- Orientation-aware extraction that consults current revisable criteria without storing them as task facts
"""

import json
import os
import re
import time
import math
import uuid
import logging
import hashlib
import threading
from typing import Any, Dict, List, Optional, Tuple

from EvolveLab.base_memory import BaseMemoryProvider
from EvolveLab.memory_types import (
    MemoryRequest,
    MemoryResponse,
    MemoryItem,
    MemoryItemType,
    MemoryStatus,
    MemoryType,
    TrajectoryData,
)


class LatticeEchoMemoryProvider(BaseMemoryProvider):
    """Layered, self-curating memory provider with adaptive reinforcement."""

    def __init__(self, config: Optional[Dict[str, Any]] = None):
        self.config = config or {}
        super().__init__(
            memory_type=MemoryType.LATTICE_ECHO_MEMORY,
            config=self.config,
        )

        self.logger = logging.getLogger(f"{__name__}.LatticeEcho")
        if not self.logger.handlers:
            handler = logging.StreamHandler()
            formatter = logging.Formatter(
                "[%(asctime)s] [LatticeEcho] [%(levelname)s] %(message)s"
            )
            handler.setFormatter(formatter)
            self.logger.addHandler(handler)
            self.logger.setLevel(logging.DEBUG)

        self.model = self.config.get("model", None)

        self.storage_dir = self.config.get(
            "storage_dir", "storage/lattice_echo_memory"
        )
        os.makedirs(self.storage_dir, exist_ok=True)

        self.database_path = self.config.get(
            "database_path",
            os.path.join(self.storage_dir, "lattice_echo_memory.json"),
        )

        self.max_semantic_memories = int(
            self.config.get("max_semantic_memories", 40)
        )
        self.max_procedural_memories = int(
            self.config.get("max_procedural_memories", 40)
        )
        self.max_episodic_memories = int(
            self.config.get("max_episodic_memories", 150)
        )
        self.memory_buffer_size = int(self.config.get("memory_buffer_size", 20))

        self.max_working_items = int(self.config.get("max_working_items", 12))
        self.max_step_summaries = int(self.config.get("max_step_summaries", 24))
        self.working_provision_interval = int(
            self.config.get("working_provision_interval", 2)
        )

        self.top_k_begin = int(self.config.get("top_k_begin", 7))
        self.max_begin_candidates = int(
            self.config.get("max_begin_candidates", 48)
        )
        self.enable_begin_guidance = bool(
            self.config.get("enable_begin_guidance", True)
        )

        self.decay_half_life_days = float(
            self.config.get("decay_half_life_days", 21.0)
        )
        self.min_context_delta_chars = int(
            self.config.get("min_context_delta_chars", 40)
        )
        self.max_trajectory_chars = int(
            self.config.get("max_trajectory_chars", 16000)
        )

        self._lock = threading.RLock()
        self._task_snapshots: Dict[str, List[str]] = {}
        self._memory_id_counter = 0
        self._task_id_counter = 0

        self.db: Optional[Dict[str, Any]] = None
        self.task_context: Dict[str, Any] = self._new_task_context(query=None)

    # =========================================================================
    # Lifecycle and storage
    # =========================================================================

    def initialize(self) -> bool:
        try:
            with self._lock:
                self.logger.info("=== Initializing Lattice Echo Memory ===")
                self.db = self._load_db()
                self._save_db()
                self.logger.info(
                    "Lattice Echo loaded: semantic=%d, procedural=%d, episodic=%d",
                    len(self.db.get("semantic", [])),
                    len(self.db.get("procedural", [])),
                    len(self.db.get("episodic", [])),
                )
                self.logger.info("=== Lattice Echo Initialization Complete ===")
                return True
        except Exception as exc:
            self.logger.error(
                "Initialization failed: %s", str(exc), exc_info=True
            )
            return False

    def _empty_db(self) -> Dict[str, Any]:
        now = time.time()
        return {
            "version": 1,
            "created_at": now,
            "semantic": [],
            "procedural": [],
            "episodic": [],
            "meta": {
                "created_at": now,
                "last_saved_at": None,
                "evictions": 0,
                "promotions": 0,
            },
        }

    def _load_db(self) -> Dict[str, Any]:
        if not os.path.exists(self.database_path):
            return self._empty_db()

        try:
            with open(self.database_path, "r", encoding="utf-8") as handle:
                db = json.load(handle)
        except Exception as exc:
            self.logger.warning(
                "Could not load Lattice Echo DB, starting empty: %s", str(exc)
            )
            return self._empty_db()

        if not isinstance(db, dict):
            return self._empty_db()

        for key in ("semantic", "procedural", "episodic"):
            if not isinstance(db.get(key), list):
                db[key] = []
        if not isinstance(db.get("meta"), dict):
            db["meta"] = {}
        db["meta"].setdefault("created_at", time.time())
        db["meta"].setdefault("last_saved_at", None)
        db["meta"].setdefault("evictions", 0)
        db["meta"].setdefault("promotions", 0)
        db.setdefault("version", 1)
        db.setdefault("created_at", time.time())
        return db

    def _save_db(self) -> None:
        if self.db is None:
            return
        try:
            os.makedirs(os.path.dirname(self.database_path) or ".", exist_ok=True)
            self.db.setdefault("meta", {})["last_saved_at"] = time.time()
            tmp_path = self.database_path + ".tmp"
            with open(tmp_path, "w", encoding="utf-8") as handle:
                json.dump(self.db, handle, ensure_ascii=False, indent=2)
            os.replace(tmp_path, self.database_path)
        except Exception as exc:
            self.logger.error("DB save failed: %s", str(exc), exc_info=True)

    # =========================================================================
    # Task context
    # =========================================================================

    def _new_task_context(
        self, task_id: Optional[str] = None, query: Optional[str] = None
    ) -> Dict[str, Any]:
        if task_id is None:
            self._task_id_counter += 1
            task_id = f"lattice_task_{self._task_id_counter}"
        return {
            "task_id": task_id,
            "query": query,
            "start_time": time.time(),
            "current_step": 0,
            "last_working_provision_step": -999,
            "begin_guidance_provided": False,
            "last_context": "",
            "working_items": [],
            "step_summaries": [],
            "used_memory_ids": [],
            "working_dirty": False,
        }

    def reset_task_context(
        self, task_id: Optional[str] = None, query: Optional[str] = None
    ) -> None:
        self.task_context = self._new_task_context(task_id=task_id, query=query)
        self.logger.debug("Task context reset: %s", self.task_context["task_id"])

    def get_task_summary(self) -> Dict[str, Any]:
        started = self.task_context.get("start_time")
        duration = time.time() - started if started else 0
        return {
            "task_id": self.task_context.get("task_id"),
            "query": self.task_context.get("query"),
            "duration_seconds": duration,
            "total_steps": self.task_context.get("current_step", 0),
            "working_items": len(self.task_context.get("working_items", [])),
            "step_summaries": len(self.task_context.get("step_summaries", [])),
            "used_memory_ids": list(
                self.task_context.get("used_memory_ids", [])
            ),
        }

    # =========================================================================
    # Core API: provide_memory
    # =========================================================================

    def provide_memory(self, request: MemoryRequest) -> MemoryResponse:
        if self.db is None:
            if not self.initialize():
                raise RuntimeError("Failed to initialize Lattice Echo memory system")

        with self._lock:
            try:
                self.logger.info("=" * 80)
                self.logger.info("LATTICE ECHO RETRIEVAL START")
                self.logger.info("Query: %s", str(request.query)[:180])
                self.logger.info("Phase: %s", request.status.value)

                if request.status == MemoryStatus.BEGIN:
                    if (
                        self.task_context.get("query") is None
                        or self.task_context.get("query") != request.query
                    ):
                        self.logger.info("New task detected; resetting task context")
                        self.reset_task_context(query=request.query)

                self.task_context["current_step"] += 1
                current_step = self.task_context["current_step"]

                memories: List[MemoryItem] = []

                if request.status == MemoryStatus.BEGIN:
                    if not self.enable_begin_guidance:
                        self.logger.info("Begin guidance disabled by config")
                    elif not self.task_context.get("begin_guidance_provided", False):
                        item = self._provide_begin_guidance(request)
                        if item is not None:
                            memories.append(item)
                            self.task_context["begin_guidance_provided"] = True
                            self.logger.info("Begin guidance provided")
                    else:
                        self.logger.info("Begin guidance already provided")

                elif request.status == MemoryStatus.IN:
                    self._auto_extract_working(request)

                    if self._should_provide_working(request, current_step):
                        item = self._provide_working_memory(request)
                        if item is not None:
                            memories.append(item)
                            self.task_context[
                                "last_working_provision_step"
                            ] = current_step
                            self.task_context["working_dirty"] = False
                            self.logger.info("Working memory provided")
                    else:
                        self.logger.info(
                            "Working memory withheld by adaptive frequency control"
                        )

                self.logger.info(
                    "LATTICE ECHO RETRIEVAL COMPLETE: %d memories", len(memories)
                )
                self.logger.info("=" * 80)

                return MemoryResponse(
                    memories=memories,
                    memory_type=MemoryType.LATTICE_ECHO_MEMORY,
                    total_count=len(memories),
                )

            except Exception as exc:
                self.logger.error(
                    "Memory retrieval failed: %s", str(exc), exc_info=True
                )
                return MemoryResponse(
                    memories=[],
                    memory_type=MemoryType.LATTICE_ECHO_MEMORY,
                    total_count=0,
                )

    # =========================================================================
    # BEGIN retrieval
    # =========================================================================

    def _provide_begin_guidance(
        self, request: MemoryRequest
    ) -> Optional[MemoryItem]:
        candidates = self._collect_begin_candidates()
        if not candidates:
            self.logger.info("No cross-task memories available")
            return None

        orientation = self._orientation_from_request(request)
        result: Optional[Dict[str, Any]] = None
        if self.model:
            result = self._llm_begin_selection(request, candidates, orientation)

        selected_ids: List[str] = []
        guidance = ""
        conflict_notes = ""

        valid_ids = {candidate["id"] for candidate in candidates}

        if result:
            selected_ids = self._normalize_selected_ids(result, valid_ids)
            guidance = str(result.get("guidance", "")).strip()
            conflict_notes = str(result.get("conflict_notes", "")).strip()

        if not selected_ids:
            top = sorted(
                candidates, key=lambda item: item["priority"], reverse=True
            )[: self.top_k_begin]
            selected_ids = [candidate["id"] for candidate in top]

        if not guidance:
            guidance = self._synthesize_from_candidates(
                candidates,
                selected_ids,
                header="Potentially relevant memories from previous tasks:",
            )

        if not guidance:
            return None

        self._record_used(selected_ids, request=request)

        self._memory_id_counter += 1
        return MemoryItem(
            id=f"lattice_echo_begin_{self._memory_id_counter}",
            content=guidance,
            metadata={
                "source": "lattice_echo_begin",
                "phase": "begin",
                "selected_ids": selected_ids,
                "conflict_notes": conflict_notes,
                "candidate_count": len(candidates),
                "layers": sorted({c["layer"] for c in candidates}),
            },
            type=MemoryItemType.TEXT,
        )

    def _collect_begin_candidates(self) -> List[Dict[str, Any]]:
        candidates: List[Dict[str, Any]] = []
        db = self.db or {}

        for layer in ("semantic", "procedural", "episodic"):
            for memory in db.get(layer, []):
                if memory.get("status", "active") != "active":
                    continue

                if layer == "semantic":
                    content = str(memory.get("content", "")).strip()
                elif layer == "procedural":
                    trigger = str(memory.get("trigger", "")).strip()
                    content = str(memory.get("content", "")).strip()
                    if trigger:
                        content = f"Trigger: {trigger} | Technique: {content}"
                else:
                    content = (
                        f"Past task: {str(memory.get('query', ''))[:220]} | "
                        f"Outcome: {memory.get('outcome', 'unknown')} | "
                        f"Summary: {str(memory.get('summary', ''))[:420]}"
                    )

                if not content:
                    continue

                score = self._priority_score(memory)
                stats = self._memory_stats(memory)
                candidates.append(
                    {
                        "id": memory.get("id"),
                        "layer": layer,
                        "content": content,
                        "priority": score,
                        "stats": stats,
                    }
                )

        candidates.sort(key=lambda item: item["priority"], reverse=True)
        return candidates[: self.max_begin_candidates]

    def _llm_begin_selection(
        self,
        request: MemoryRequest,
        candidates: List[Dict[str, Any]],
        orientation: List[str],
    ) -> Optional[Dict[str, Any]]:
        if not self.model:
            return None

        candidate_lines = []
        for candidate in candidates:
            candidate_lines.append(
                f"- ID: {candidate['id']} | layer={candidate['layer']} | "
                f"priority={candidate['priority']:.3f} | {candidate['stats']}\n"
                f"  {candidate['content']}"
            )

        orientation_text = self._format_orientation(orientation)

        prompt = f"""You are the retrieval curator for a layered agent memory system.

Current revisable orientation criteria (provisional standards only; do not copy them into guidance):
{orientation_text}

Task query:
{request.query}

Candidate memories:
{chr(10).join(candidate_lines)}

Tasks:
1. Select up to {self.top_k_begin} memories that are genuinely relevant to the current task.
2. Synthesize concise, task-specific guidance from the selected memories.
3. Note any conflicts, uncertainty, or reasons to use the memories cautiously.
4. Use the orientation criteria only to judge relevance and salience. Do not restate the criteria.

Output JSON:
{{
  "selected_ids": ["memory_id_1", "memory_id_2"],
  "guidance": "concise guidance with actionable suggestions",
  "conflict_notes": "optional conflicts or uncertainty, or empty string"
}}

Rules:
- Select IDs only from the candidate list.
- Guidance should be brief: no more than 6 bullet-like sentences.
- Frame as suggestions, not commands.
- If no candidate is useful, return an empty selected_ids list and empty guidance.

JSON only:"""

        response = self._call_llm(prompt)
        parsed = self._parse_json_response(response)
        if isinstance(parsed, dict):
            return parsed
        return None

    def _synthesize_from_candidates(
        self,
        candidates: List[Dict[str, Any]],
        selected_ids: List[str],
        header: str,
    ) -> str:
        by_id = {candidate["id"]: candidate for candidate in candidates}
        lines = [header]
        for memory_id in selected_ids:
            candidate = by_id.get(memory_id)
            if not candidate:
                continue
            content = str(candidate["content"]).strip()
            if len(content) > 420:
                content = content[:417] + "..."
            lines.append(f"- [{candidate['layer']}] {content}")

        if len(lines) == 1:
            return ""
        lines.append(
            "- Treat these as conditional hints; verify against the current task evidence."
        )
        return "\n".join(lines)

    # =========================================================================
    # IN-phase working memory
    # =========================================================================

    def _should_provide_working(
        self, request: MemoryRequest, current_step: int
    ) -> bool:
        params = request.additional_params or {}
        if bool(params.get("force_memory_provision", False)):
            return True

        last = int(self.task_context.get("last_working_provision_step", -999))
        steps_since = current_step - last
        if steps_since >= self.working_provision_interval:
            return True

        if self.task_context.get("working_dirty", False) and steps_since >= 1:
            return True

        return False

    def _calculate_context_delta(self, current_context: str) -> str:
        current = str(current_context or "").strip()
        last = str(self.task_context.get("last_context", "") or "").strip()

        if not last:
            return current

        if current.startswith(last):
            delta = current[len(last) :].strip()
            return delta if delta else current

        return current

    def _auto_extract_working(self, request: MemoryRequest) -> None:
        if not self.model:
            return

        try:
            context_delta = self._calculate_context_delta(request.context)
            self.task_context["last_context"] = request.context

            if len(context_delta.strip()) < self.min_context_delta_chars:
                return

            current_items = self.task_context.get("working_items", [])
            current_items_text = (
                "\n".join(
                    f"- ID={item['id']} | kind={item.get('kind', 'finding')} | "
                    f"importance={item.get('importance', 0.5):.2f} | {item['content']}"
                    for item in current_items
                )
                if current_items
                else "(no working items yet)"
            )

            prev_steps = self._build_prev_steps_summary()
            orientation = self._orientation_from_request(request)
            orientation_text = self._format_orientation(orientation)

            prompt = f"""You are maintaining the working memory of an AI agent.

Current revisable orientation criteria (provisional standards only; do not copy them as task facts):
{orientation_text}

Original task:
{request.query}

Previous step summaries:
{prev_steps}

Current working memory:
{current_items_text}

New information from the current step:
{context_delta}

Perform two tasks:
1. Summarize what happened in this step.
2. Update the working memory.

Working memory should preserve:
- task constraints and output requirements
- key data values, units, dates, or conditions discovered
- important findings, contradictions, or decisions
- unresolved questions that affect next actions

Do not preserve:
- generic system/format instructions
- tool protocol reminders
- redundant or superseded intermediate details

Output JSON:
{{
  "step_summary": "2-3 sentence summary of this step",
  "working_updates": {{
    "add": [
      {{"content": "concise fact, constraint, datum, or finding", "kind": "constraint|datum|finding|plan|question", "importance": 0.0}}
    ],
    "remove_ids": ["working_id_to_remove"],
    "merge": [
      {{"target_id": "working_id_to_update", "content": "updated concise content", "importance": 0.0}}
    ]
  }}
}}

Rules:
- Add at most 3 items.
- Each item must be concise and task-related.
- Use remove_ids only for superseded or irrelevant items.
- Use merge to sharpen or update an existing item.
- If nothing should change, use empty lists.

JSON only:"""

            response = self._call_llm(prompt)
            parsed = self._parse_json_response(response)
            if not isinstance(parsed, dict):
                self.logger.warning("Working-memory extraction returned no valid JSON")
                return

            step_summary = str(parsed.get("step_summary", "")).strip()
            if step_summary:
                self.task_context["step_summaries"].append(
                    {
                        "step": self.task_context["current_step"],
                        "summary": step_summary,
                        "timestamp": time.time(),
                    }
                )
                if len(self.task_context["step_summaries"]) > self.max_step_summaries:
                    self.task_context["step_summaries"] = self.task_context[
                        "step_summaries"
                    ][-self.max_step_summaries :]
                self.task_context["working_dirty"] = True

            updates = parsed.get("working_updates")
            if not isinstance(updates, dict):
                updates = {
                    key: parsed.get(key)
                    for key in ("add", "remove_ids", "merge")
                    if key in parsed
                }

            self._apply_working_updates(updates)

            if (
                len(self.task_context.get("working_items", []))
                > self.max_working_items
            ):
                self._curate_working_set()

        except Exception as exc:
            self.logger.warning(
                "Working-memory auto-extraction failed: %s", str(exc)
            )

    def _apply_working_updates(self, updates: Dict[str, Any]) -> None:
        if not isinstance(updates, dict):
            return

        now = time.time()

        for entry in updates.get("add", []) or []:
            if isinstance(entry, dict):
                content = str(entry.get("content", "")).strip()
                kind = str(entry.get("kind", "finding")).strip() or "finding"
                try:
                    importance = float(entry.get("importance", 0.6))
                except Exception:
                    importance = 0.6
            else:
                content = str(entry).strip()
                kind = "finding"
                importance = 0.6

            if len(content) >= 8:
                self._add_working_item(content, kind, importance)

        remove_ids = updates.get("remove_ids", []) or []
        if isinstance(remove_ids, list) and remove_ids:
            remove_set = {str(item) for item in remove_ids}
            before = len(self.task_context.get("working_items", []))
            self.task_context["working_items"] = [
                item
                for item in self.task_context.get("working_items", [])
                if item.get("id") not in remove_set
            ]
            if len(self.task_context["working_items"]) != before:
                self.task_context["working_dirty"] = True

        for entry in updates.get("merge", []) or []:
            if not isinstance(entry, dict):
                continue
            target_id = str(entry.get("target_id", "")).strip()
            content = str(entry.get("content", "")).strip()
            if not target_id or len(content) < 8:
                continue
            for item in self.task_context.get("working_items", []):
                if item.get("id") == target_id:
                    item["content"] = content
                    item["signature"] = self._compute_signature(content)
                    item["updated_at"] = now
                    try:
                        item["importance"] = max(
                            float(item.get("importance", 0.5)),
                            float(entry.get("importance", item.get("importance", 0.5))),
                        )
                    except Exception:
                        pass
                    self.task_context["working_dirty"] = True
                    break

    def _add_working_item(
        self, content: str, kind: str, importance: float
    ) -> None:
        content = str(content).strip()
        if not content:
            return

        importance = max(0.0, min(1.0, float(importance)))
        signature = self._compute_signature(content)
        now = time.time()

        for item in self.task_context.get("working_items", []):
            if item.get("signature") == signature:
                item["importance"] = max(
                    float(item.get("importance", 0.0)), importance
                )
                item["updated_at"] = now
                self.task_context["working_dirty"] = True
                return

        self.task_context.setdefault("working_items", []).append(
            {
                "id": f"work_{uuid.uuid4().hex[:10]}",
                "content": content,
                "kind": kind,
                "importance": importance,
                "signature": signature,
                "created_at": now,
                "updated_at": now,
            }
        )
        self.task_context["working_dirty"] = True

    def _curate_working_set(self) -> None:
        items = self.task_context.get("working_items", [])
        if len(items) <= self.max_working_items:
            return

        if self.model:
            item_lines = [
                f"- ID={item['id']} | kind={item.get('kind', 'finding')} | "
                f"importance={item.get('importance', 0.5):.2f} | {item['content']}"
                for item in items
            ]

            prompt = f"""You are curating the working memory of an AI agent.

Task:
{self.task_context.get('query', '')}

Recent execution trace:
{self._build_prev_steps_summary()}

Current working items:
{chr(10).join(item_lines)}

Select exactly {self.max_working_items} items to keep.

Keep priorities:
- task constraints and output format requirements
- critical data values, units, dates, or conditions
- unresolved findings or contradictions that affect next actions
- decisions that constrain later steps

Remove:
- superseded or redundant details
- low-value intermediate observations
- items no longer relevant to the next action

Output JSON:
{{"keep_ids": ["id1", "id2"]}}

JSON only:"""

            response = self._call_llm(prompt)
            parsed = self._parse_json_response(response)
            if isinstance(parsed, dict):
                raw = parsed.get("keep_ids", parsed.get("keep", []))
                if isinstance(raw, list):
                    valid_ids = {item.get("id") for item in items}
                    keep_ids = []
                    for raw_id in raw:
                        raw_id = str(raw_id)
                        if raw_id in valid_ids and raw_id not in keep_ids:
                            keep_ids.append(raw_id)

                    if keep_ids and len(keep_ids) <= self.max_working_items:
                        keep_set = set(keep_ids)
                        self.task_context["working_items"] = [
                            item for item in items if item.get("id") in keep_set
                        ]
                        self.task_context["working_dirty"] = True
                        return

        # Fallback: keep highest-importance and most recent items.
        ranked = sorted(
            items,
            key=lambda item: (
                float(item.get("importance", 0.0)),
                float(item.get("updated_at", item.get("created_at", 0.0))),
            ),
            reverse=True,
        )
        self.task_context["working_items"] = ranked[: self.max_working_items]
        self.task_context["working_dirty"] = True

    def _provide_working_memory(
        self, request: MemoryRequest
    ) -> Optional[MemoryItem]:
        items = self.task_context.get("working_items", [])
        summaries = self.task_context.get("step_summaries", [])

        if not items and not summaries:
            return None

        lines: List[str] = ["**Lattice Echo Working Memory for Current Task**"]

        if items:
            lines.append("Curated constraints, data, findings, or questions:")
            for item in items:
                kind = str(item.get("kind", "finding")).upper()
                importance = float(item.get("importance", 0.5))
                lines.append(
                    f"- [{kind}; importance={importance:.2f}] {item.get('content', '')}"
                )
        else:
            lines.append("No curated working items yet.")

        if summaries:
            lines.append("")
            lines.append("Recent execution trace:")
            for summary in summaries[-6:]:
                lines.append(
                    f"- Step {summary.get('step')}: {summary.get('summary', '')}"
                )

        lines.append(
            "Use this as task-local memory; verify stale or uncertain details against current evidence."
        )

        self._memory_id_counter += 1
        return MemoryItem(
            id=f"lattice_echo_working_{self._memory_id_counter}",
            content="\n".join(lines),
            metadata={
                "source": "lattice_echo_working",
                "phase": "in",
                "working_item_count": len(items),
                "step_summary_count": len(summaries),
                "step": self.task_context.get("current_step", 0),
            },
            type=MemoryItemType.TEXT,
        )

    def _build_prev_steps_summary(self) -> str:
        summaries = self.task_context.get("step_summaries", [])
        if not summaries:
            return "No previous steps."
        return "\n".join(
            f"Step {entry.get('step')}: {entry.get('summary', '')}"
            for entry in summaries[-8:]
        )

    # =========================================================================
    # Core API: take_in_memory
    # =========================================================================

    def take_in_memory(self, trajectory_data: TrajectoryData) -> Tuple[bool, str]:
        if self.db is None:
            if not self.initialize():
                return (False, "Failed to initialize Lattice Echo memory system")

        with self._lock:
            try:
                self.logger.info("=" * 80)
                self.logger.info("LATTICE ECHO INGESTION START")
                self.logger.info("Query: %s", str(trajectory_data.query)[:180])

                metadata = trajectory_data.metadata or {}
                is_success = self._is_trajectory_success(trajectory_data)
                full_query = (
                    metadata.get("full_query") or trajectory_data.query or ""
                )

                self._update_used_outcomes(full_query, is_success)

                learning = self._extract_learning(trajectory_data, is_success)
                absorbed = 0

                if learning:
                    absorbed += self._apply_learning(
                        trajectory_data, learning, is_success
                    )

                if not learning or not learning.get("episodic_summary"):
                    if self._add_episodic_fallback(trajectory_data, is_success):
                        absorbed += 1

                self._prune_pool("semantic", self.max_semantic_memories)
                self._prune_pool("procedural", self.max_procedural_memories)
                self._prune_pool("episodic", self.max_episodic_memories)

                self._save_db()
                self._cleanup_snapshot(full_query, trajectory_data.query)

                self.logger.info(
                    "LATTICE ECHO INGESTION COMPLETE: %d additions/updates",
                    absorbed,
                )
                self.logger.info("=" * 80)

                return (
                    True,
                    f"Lattice Echo absorbed {absorbed} memory additions/updates",
                )

            except Exception as exc:
                self.logger.error(
                    "Memory ingestion failed: %s", str(exc), exc_info=True
                )
                return (False, f"Ingestion failed: {str(exc)}")

    def _update_used_outcomes(self, query: str, is_success: bool) -> None:
        used_ids = list(self.task_context.get("used_memory_ids", []))

        if not used_ids and query:
            lookup_queries = [query]
            if self.task_context.get("query"):
                lookup_queries.append(self.task_context["query"])

            for lookup in lookup_queries:
                key = self._compute_signature(str(lookup))
                snapshot = self._task_snapshots.get(key, [])
                if snapshot:
                    used_ids = list(snapshot)
                    self.logger.info(
                        "Restored %d used memory IDs from snapshot", len(used_ids)
                    )
                    break

        if not used_ids:
            self.logger.info("No used memory IDs to reinforce")
            return

        now = time.time()
        updated = 0
        for memory_id in used_ids:
            memory = self._find_memory_by_id(memory_id)
            if not memory:
                continue
            if is_success:
                memory["success_count"] = int(memory.get("success_count", 0)) + 1
                memory["confidence"] = min(
                    1.0, float(memory.get("confidence", 0.5)) + 0.02
                )
            else:
                memory["failure_count"] = int(memory.get("failure_count", 0)) + 1
                memory["confidence"] = max(
                    0.05, float(memory.get("confidence", 0.5)) - 0.03
                )
            memory["updated_at"] = now
            updated += 1

        self.logger.info("Reinforced %d used memories", updated)

    def _extract_learning(
        self, trajectory_data: TrajectoryData, is_success: bool
    ) -> Optional[Dict[str, Any]]:
        if not self.model:
            return None

        try:
            trajectory_text = json.dumps(
                trajectory_data.trajectory or [], ensure_ascii=False
            )
            trajectory_text = self._compact_text(
                trajectory_text, self.max_trajectory_chars
            )
            result_text = self._compact_text(
                str(trajectory_data.result), 2500
            )

            metadata = trajectory_data.metadata or {}
            orientation = self._orientation_from_trajectory(trajectory_data)
            orientation_text = self._format_orientation(orientation)

            outcome_text = "SUCCESS" if is_success else "FAILURE"

            prompt = f"""You are extracting reusable memory from a completed agent task.

Current revisable orientation criteria (provisional standards only; use them to judge what is worth learning, but do not copy them as task facts):
{orientation_text}

Outcome: {outcome_text}

Task query:
{trajectory_data.query}

Result:
{result_text}

Trajectory:
{trajectory_text}

Extract:
1. A compact episodic summary of what happened.
2. Reusable semantic insights: strategic principles, decision criteria, or cautions.
3. Reusable procedural techniques: triggers, tool usage patterns, or edge-case handling.
4. Pitfalls if the outcome was failure or if success contained fragile steps.

Output JSON:
{{
  "episodic_summary": "2-4 sentence summary of the attempt and outcome",
  "semantic": [
    {{"content": "reusable strategic insight", "tags": ["tag1"], "confidence": 0.0}}
  ],
  "procedural": [
    {{"content": "reusable operational technique", "trigger": "when this applies", "tags": ["tag1"], "confidence": 0.0}}
  ],
  "pitfalls": [
    {{"content": "specific failure mode or caution", "tags": ["pitfall"], "confidence": 0.0}}
  ],
  "evidence": ["short evidence fragment from the trajectory"]
}}

Rules:
- Max 3 semantic, 3 procedural, and 3 pitfalls.
- Focus on reusable patterns, not task-specific final answers.
- Do not copy the orientation criteria into memories.
- For failures, prefer pitfalls and revised strategies.
- Confidence must be between 0 and 1.
- If a category has nothing valuable, return an empty list.

JSON only:"""

            response = self._call_llm(prompt)
            parsed = self._parse_json_response(response)
            normalized = self._normalize_learning(parsed, is_success)
            return normalized

        except Exception as exc:
            self.logger.warning("Learning extraction failed: %s", str(exc))
            return None

    def _normalize_learning(
        self, raw: Any, is_success: bool
    ) -> Optional[Dict[str, Any]]:
        if not isinstance(raw, dict):
            return None

        semantic = self._normalize_memory_entries(
            raw.get("semantic", []), default_kind="strategic", is_success=is_success
        )
        procedural = self._normalize_memory_entries(
            raw.get("procedural", []),
            default_kind="operational",
            is_success=is_success,
        )
        pitfalls = self._normalize_memory_entries(
            raw.get("pitfalls", []), default_kind="pitfall", is_success=is_success
        )
        for pitfall in pitfalls:
            pitfall["kind"] = "pitfall"
            pitfall["tags"] = sorted(set(pitfall.get("tags", []) + ["pitfall"]))
            pitfall["confidence"] = min(0.6, pitfall.get("confidence", 0.5))

        evidence_raw = raw.get("evidence", [])
        evidence: List[str] = []
        if isinstance(evidence_raw, list):
            for item in evidence_raw:
                text = str(item).strip()
                if text:
                    evidence.append(text)
        evidence = evidence[:6]

        return {
            "episodic_summary": str(raw.get("episodic_summary", "")).strip(),
            "semantic": semantic,
            "procedural": procedural,
            "pitfalls": pitfalls,
            "evidence": evidence,
        }

    def _normalize_memory_entries(
        self, entries: Any, default_kind: str, is_success: bool
    ) -> List[Dict[str, Any]]:
        if not isinstance(entries, list):
            return []

        normalized: List[Dict[str, Any]] = []
        for entry in entries:
            if isinstance(entry, str):
                content = entry
                tags: List[str] = []
                confidence = 0.55 if is_success else 0.45
                kind = default_kind
                trigger = ""
            elif isinstance(entry, dict):
                content = str(entry.get("content", ""))
                raw_tags = entry.get("tags", [])
                if isinstance(raw_tags, str):
                    tags = [raw_tags]
                elif isinstance(raw_tags, list):
                    tags = [str(tag) for tag in raw_tags if str(tag).strip()]
                else:
                    tags = []
                try:
                    confidence = float(entry.get("confidence", 0.55))
                except Exception:
                    confidence = 0.55
                kind = str(entry.get("kind", default_kind)) or default_kind
                trigger = str(entry.get("trigger", "")).strip()
            else:
                continue

            content = content.strip()
            if len(content) < 15:
                continue

            confidence = max(0.05, min(1.0, confidence))
            if not is_success:
                confidence = max(0.1, confidence - 0.1)

            normalized.append(
                {
                    "content": content,
                    "tags": sorted(set(tags)),
                    "confidence": confidence,
                    "kind": kind,
                    "trigger": trigger,
                }
            )

        return normalized[:3]

    def _apply_learning(
        self,
        trajectory_data: TrajectoryData,
        learning: Dict[str, Any],
        is_success: bool,
    ) -> int:
        absorbed = 0

        summary = str(learning.get("episodic_summary", "")).strip()
        if summary:
            if self._add_episodic(
                trajectory_data, summary, is_success, learning
            ):
                absorbed += 1

        evidence = learning.get("evidence", [])

        for entry in learning.get("semantic", []) or []:
            if self._upsert_memory(
                layer="semantic",
                content=entry["content"],
                kind=entry.get("kind", "strategic"),
                tags=entry.get("tags", []),
                confidence=entry.get("confidence", 0.55),
                source="trajectory",
                evidence=evidence,
                trigger="",
            ):
                absorbed += 1

        for entry in learning.get("procedural", []) or []:
            if self._upsert_memory(
                layer="procedural",
                content=entry["content"],
                kind=entry.get("kind", "operational"),
                tags=entry.get("tags", []),
                confidence=entry.get("confidence", 0.55),
                source="trajectory",
                evidence=evidence,
                trigger=entry.get("trigger", ""),
            ):
                absorbed += 1

        for entry in learning.get("pitfalls", []) or []:
            if self._upsert_memory(
                layer="semantic",
                content=entry["content"],
                kind="pitfall",
                tags=entry.get("tags", ["pitfall"]),
                confidence=entry.get("confidence", 0.5),
                source="trajectory",
                evidence=evidence,
                trigger="",
            ):
                absorbed += 1

        return absorbed

    def _upsert_memory(
        self,
        layer: str,
        content: str,
        kind: str,
        tags: List[str],
        confidence: float,
        source: str,
        evidence: List[str],
        trigger: str,
    ) -> bool:
        if not self.db or layer not in ("semantic", "procedural"):
            return False

        content = str(content).strip()
        if len(content) < 15:
            return False

        confidence = max(0.05, min(1.0, float(confidence)))
        tags = sorted({str(tag).strip() for tag in tags if str(tag).strip()})
        signature = self._compute_signature(content)
        now = time.time()

        pool = self.db[layer]
        for memory in pool:
            if memory.get("signature") == signature:
                memory["confidence"] = max(
                    float(memory.get("confidence", 0.5)), confidence
                )
                memory["updated_at"] = now
                memory["tags"] = sorted(
                    set(memory.get("tags", []) + tags)
                )
                if trigger and layer == "procedural":
                    memory["trigger"] = trigger
                existing_evidence = memory.get("evidence", []) or []
                for item in evidence:
                    if item not in existing_evidence:
                        existing_evidence.append(item)
                memory["evidence"] = existing_evidence[-8:]
                return False

        prefix = "sem" if layer == "semantic" else "proc"
        new_memory = {
            "id": f"{prefix}_{uuid.uuid4().hex[:12]}",
            "content": content,
            "kind": kind,
            "tags": tags,
            "confidence": confidence,
            "trigger": trigger if layer == "procedural" else "",
            "usage_count": 0,
            "success_count": 0,
            "failure_count": 0,
            "created_at": now,
            "updated_at": now,
            "last_used_at": None,
            "status": "active",
            "signature": signature,
            "source": source,
            "evidence": list(evidence)[-8:],
        }
        pool.append(new_memory)
        return True

    def _add_episodic(
        self,
        trajectory_data: TrajectoryData,
        summary: str,
        is_success: bool,
        learning: Dict[str, Any],
    ) -> bool:
        if not self.db:
            return False

        summary = str(summary).strip()
        if not summary:
            return False

        query = str(trajectory_data.query or "")
        signature = self._compute_signature(query + "||" + summary)
        now = time.time()

        lessons: List[str] = []
        for key in ("semantic", "procedural", "pitfalls"):
            for entry in learning.get(key, []) or []:
                if isinstance(entry, dict):
                    text = str(entry.get("content", "")).strip()
                else:
                    text = str(entry).strip()
                if text:
                    lessons.append(text)
        lessons = lessons[:6]

        for memory in self.db.get("episodic", []):
            if memory.get("signature") == signature:
                memory["confidence"] = max(
                    float(memory.get("confidence", 0.5)),
                    0.7 if is_success else 0.55,
                )
                memory["updated_at"] = now
                return False

        result_preview = self._compact_text(str(trajectory_data.result), 900)

        self.db.setdefault("episodic", []).append(
            {
                "id": f"epi_{uuid.uuid4().hex[:12]}",
                "query": query,
                "summary": summary,
                "outcome": "success" if is_success else "failure",
                "lessons": lessons,
                "result_preview": result_preview,
                "tags": [],
                "confidence": 0.7 if is_success else 0.55,
                "usage_count": 0,
                "success_count": 0,
                "failure_count": 0,
                "created_at": now,
                "updated_at": now,
                "last_used_at": None,
                "status": "active",
                "signature": signature,
            }
        )
        return True

    def _add_episodic_fallback(
        self, trajectory_data: TrajectoryData, is_success: bool
    ) -> bool:
        result_preview = self._compact_text(str(trajectory_data.result), 700)
        outcome = "success" if is_success else "failure"
        summary = (
            f"Task: {str(trajectory_data.query)[:320]}. "
            f"Outcome: {outcome}. "
            f"Result/observation preview: {result_preview}"
        )
        learning = {
            "semantic": [],
            "procedural": [],
            "pitfalls": [],
            "evidence": [],
        }
        return self._add_episodic(
            trajectory_data, summary, is_success, learning
        )

    # =========================================================================
    # Pruning and scoring
    # =========================================================================

    def _priority_score(self, memory: Dict[str, Any]) -> float:
        now = time.time()
        created = float(memory.get("created_at", now) or now)
        last_used = memory.get("last_used_at")
        anchor = float(last_used) if last_used else float(
            memory.get("updated_at", created) or created
        )

        age_days = max(0.0, (now - anchor) / 86400.0)
        half_life = max(0.1, self.decay_half_life_days)
        decay = 0.5 ** (age_days / half_life)

        usage = float(memory.get("usage_count", 0))
        success = float(memory.get("success_count", 0))
        failure = float(memory.get("failure_count", 0))
        confidence = float(memory.get("confidence", 0.5))

        success_rate = (success + 1.0) / (usage + 2.0)
        usage_evidence = min(1.0, math.log1p(usage) / 3.0)
        failure_penalty = 1.0 - 0.35 * min(1.0, failure / (usage + 1.0))

        score = (
            0.55 * confidence
            + 0.22 * success_rate
            + 0.15 * usage_evidence
            + 0.08 * decay
        )
        score *= failure_penalty
        return max(0.0, min(1.0, score))

    def _memory_stats(self, memory: Dict[str, Any]) -> str:
        usage = int(memory.get("usage_count", 0))
        success = int(memory.get("success_count", 0))
        failure = int(memory.get("failure_count", 0))
        confidence = float(memory.get("confidence", 0.5))
        return (
            f"used={usage}, success={success}, failure={failure}, "
            f"confidence={confidence:.2f}"
        )

    def _prune_pool(self, layer: str, max_size: int) -> None:
        if not self.db or layer not in self.db:
            return
        pool = self.db[layer]
        if len(pool) <= max_size + self.memory_buffer_size:
            return

        num_to_remove = len(pool) - max_size
        remove_ids: List[str] = []

        if self.model:
            remove_ids = self._llm_select_removals(
                pool, num_to_remove, layer
            )

        if remove_ids:
            remove_set = set(remove_ids)
            kept = [
                memory
                for memory in pool
                if memory.get("id") not in remove_set
            ]
            if len(kept) > max_size:
                kept = self._fallback_prune_list(kept, max_size)
        else:
            kept = self._fallback_prune_list(pool, max_size)

        removed_count = len(pool) - len(kept)
        if removed_count > 0:
            self.db["meta"]["evictions"] = int(
                self.db.get("meta", {}).get("evictions", 0)
            ) + removed_count
        self.db[layer] = kept

    def _fallback_prune_list(
        self, pool: List[Dict[str, Any]], max_size: int
    ) -> List[Dict[str, Any]]:
        ranked = sorted(
            pool,
            key=lambda memory: (
                self._priority_score(memory),
                float(memory.get("created_at", 0)),
            ),
            reverse=True,
        )
        return ranked[:max_size]

    def _llm_select_removals(
        self, pool: List[Dict[str, Any]], num_to_remove: int, layer: str
    ) -> List[str]:
        if not self.model or not pool:
            return []

        lines = []
        for index, memory in enumerate(pool, 1):
            lines.append(
                f"{index}. ID={memory.get('id')} | "
                f"priority={self._priority_score(memory):.3f} | "
                f"{self._memory_stats(memory)}\n"
                f"   {str(memory.get('content', memory.get('summary', '')))[:500]}"
            )

        prompt = f"""You are pruning a memory pool in a layered agent memory system.

Memory layer: {layer.upper()}
Current size: {len(pool)}
Target maximum: {len(pool) - num_to_remove}

Memories:
{chr(10).join(lines)}

Select exactly {num_to_remove} memories to REMOVE.

Priorities:
- Remove low-confidence, rarely used, or failure-heavy memories first.
- Remove vague or redundant guidance.
- Preserve memories with strong success evidence, high relevance, and specific actionable content.
- For episodic memories, preserve diverse outcomes and useful lessons.

Output JSON:
{{"remove_ids": ["id1", "id2"]}}

Use IDs exactly as shown. JSON only:"""

        response = self._call_llm(prompt)
        parsed = self._parse_json_response(response)
        if not isinstance(parsed, dict):
            return []

        raw = parsed.get("remove_ids", parsed.get("remove", []))
        if not isinstance(raw, list):
            return []

        valid_ids = {str(memory.get("id")) for memory in pool}
        remove_ids: List[str] = []
        seen = set()

        for item in raw:
            if isinstance(item, int) and 1 <= item <= len(pool):
                memory_id = str(pool[item - 1].get("id"))
            else:
                memory_id = str(item)
            if memory_id in valid_ids and memory_id not in seen:
                remove_ids.append(memory_id)
                seen.add(memory_id)

        return remove_ids[:num_to_remove]

    # =========================================================================
    # Memory lookup and snapshots
    # =========================================================================

    def _find_memory_by_id(self, memory_id: str) -> Optional[Dict[str, Any]]:
        if not self.db or not memory_id:
            return None
        memory_id = str(memory_id)
        for layer in ("semantic", "procedural", "episodic"):
            for memory in self.db.get(layer, []):
                if str(memory.get("id")) == memory_id:
                    return memory
        return None

    def _record_used(
        self, memory_ids: List[str], request: Optional[MemoryRequest] = None
    ) -> None:
        if not memory_ids:
            return

        now = time.time()
        unique_ids: List[str] = []

        for memory_id in memory_ids:
            memory = self._find_memory_by_id(memory_id)
            if not memory:
                continue
            memory["usage_count"] = int(memory.get("usage_count", 0)) + 1
            memory["last_used_at"] = now
            memory["updated_at"] = now
            if memory_id not in unique_ids:
                unique_ids.append(memory_id)

        if not unique_ids:
            return

        existing = self.task_context.setdefault("used_memory_ids", [])
        for memory_id in unique_ids:
            if memory_id not in existing:
                existing.append(memory_id)

        if request is not None:
            snapshot_query = self._snapshot_query_from_request(request)
            if snapshot_query:
                key = self._compute_signature(snapshot_query)
                self._task_snapshots[key] = list(existing)
                self.logger.info(
                    "Saved task snapshot: hash=%s..., ids=%d",
                    key[:16],
                    len(existing),
                )

    def _snapshot_query_from_request(self, request: MemoryRequest) -> str:
        params = request.additional_params or {}
        for key in ("full_query", "task_query", "original_query"):
            value = params.get(key)
            if value:
                return str(value)
        return str(request.query or "")

    def _cleanup_snapshot(self, full_query: str, fallback_query: str) -> None:
        for query in (full_query, fallback_query):
            if not query:
                continue
            key = self._compute_signature(str(query))
            if key in self._task_snapshots:
                del self._task_snapshots[key]
                self.logger.info("Cleaned task snapshot: hash=%s...", key[:16])

        current_query = self.task_context.get("query")
        if current_query and full_query:
            if self._compute_signature(str(current_query)) == self._compute_signature(
                str(full_query)
            ):
                self.task_context["used_memory_ids"] = []

    # =========================================================================
    # Orientation handling
    # =========================================================================

    def _orientation_from_request(self, request: MemoryRequest) -> List[str]:
        items = None
        if request and request.additional_params:
            items = request.additional_params.get("philo_orientation_items")
        if items is None:
            items = self.config.get("philo_orientation_items", [])
        return self._clean_orientation_items(items)

    def _orientation_from_trajectory(
        self, trajectory_data: TrajectoryData
    ) -> List[str]:
        items = None
        metadata = trajectory_data.metadata or {}
        items = metadata.get("philo_orientation_items")
        if items is None:
            items = self.config.get("philo_orientation_items", [])
        return self._clean_orientation_items(items)

    def _clean_orientation_items(self, items: Any) -> List[str]:
        if not isinstance(items, list):
            return []
        cleaned: List[str] = []
        for item in items:
            text = str(item).strip()
            if text:
                cleaned.append(text)
        return cleaned

    def _format_orientation(self, items: List[str]) -> str:
        if not items:
            return "(none supplied)"
        return "\n".join(f"- {item}" for item in items)

    # =========================================================================
    # Utilities
    # =========================================================================

    def _is_trajectory_success(self, trajectory_data: TrajectoryData) -> bool:
        metadata = trajectory_data.metadata or {}
        if metadata.get("is_correct") is True:
            return True
        if metadata.get("task_success") is True:
            return True
        if metadata.get("outcome") == "success":
            return True
        return False

    def _compute_signature(self, text: str) -> str:
        normalized = re.sub(r"\s+", " ", str(text).strip().lower())
        return hashlib.sha256(normalized.encode("utf-8")).hexdigest()

    def _compact_text(self, text: str, max_length: int) -> str:
        text = str(text or "").strip()
        if len(text) <= max_length:
            return text
        half = max(1, max_length // 2)
        return text[:half] + "\n... [truncated] ...\n" + text[-half:]

    def _normalize_selected_ids(
        self, result: Dict[str, Any], valid_ids: set
    ) -> List[str]:
        raw = (
            result.get("selected_ids")
            or result.get("selected")
            or result.get("ids")
            or []
        )
        if not isinstance(raw, list):
            return []

        selected: List[str] = []
        for item in raw:
            memory_id = str(item)
            if memory_id in valid_ids and memory_id not in selected:
                selected.append(memory_id)
        return selected

    def _parse_json_response(self, text: str) -> Optional[Any]:
        if not text or not str(text).strip():
            return None

        text = str(text).strip()

        try:
            return json.loads(text)
        except Exception:
            pass

        patterns = [
            r"```json\s*\n?(.*?)```",
            r"```[^\n]*\n?(.*?)```",
        ]
        for pattern in patterns:
            match = re.search(pattern, text, re.DOTALL)
            if match:
                try:
                    return json.loads(match.group(1).strip())
                except Exception:
                    pass

        object_pattern = r"\{[^{}]*(?:\{[^{}]*\}[^{}]*)*\}"
        array_pattern = r"\[[^\[\]]*(?:\[[^\[\]]*\][^\[\]]*)*\]"

        for pattern in (object_pattern, array_pattern):
            matches = re.findall(pattern, text, re.DOTALL)
            for candidate in matches:
                try:
                    return json.loads(candidate)
                except Exception:
                    continue

        return None

    def _call_llm(self, prompt: str) -> str:
        if not self.model:
            return ""
        try:
            messages = [
                {
                    "role": "user",
                    "content": [{"type": "text", "text": prompt}],
                }
            ]
            response = self.model(messages)
            content = getattr(response, "content", response)

            if isinstance(content, list):
                parts = []
                for item in content:
                    if isinstance(item, dict):
                        parts.append(str(item.get("text", item)))
                    else:
                        parts.append(str(item))
                content = "\n".join(parts)

            return str(content).strip()
        except Exception as exc:
            self.logger.error("LLM call failed: %s", str(exc), exc_info=True)
            return ""

