"""
Praxis Anchor Memory Provider

A contract-aware, reliability-calibrated memory system that anchors agent
execution to explicit deliverable obligations and learns from both successes
and failures.

Key innovations over the template:
1. Deliverable-Contract Ledger: decomposes the query into a checkable contract
   at BEGIN and re-derives per-item completion status during execution.
2. Reliability ledger with smoothed priors: distinguishes exposure from
   usefulness (followed vs. merely injected), labels evidence maturity, and
   forces annealed exploration of untested memories.
3. Failure-mode (pitfall) ingestion: unsuccessful trajectories produce
   preventive checks instead of being discarded.
4. Role x stage taxonomy: LLM-assigned functional roles and applicability
   stages drive bounded pre-filtering and slot allocation during synthesis.
5. Attribution integrity: task-scoped snapshots with exposure/following split,
   concurrency-tolerant lookup, and utility-based lifecycle curation.
"""

import json
import os
import re
import time
import logging
import hashlib
import threading
import copy
from datetime import datetime, timezone
from typing import Any, Dict, List, Optional, Tuple

from EvolveLab.base_memory import BaseMemoryProvider
from EvolveLab.memory_types import (
    MemoryRequest,
    MemoryResponse,
    MemoryItem,
    MemoryItemType,
    MemoryStatus,
    MemoryType,
    TrajectoryData,
)


# ---------------------------------------------------------------------------
# Cold-start memories (deliberately minimal and task-family oriented)
# ---------------------------------------------------------------------------
COLDSTART_STRATEGIC = [
    {
        "content": "Before producing a long deliverable, enumerate its required sections and their minimum extent, then track each as an explicit obligation.",
