    },
    {
        "content": "For numerical tasks, identify all units explicitly and track unit conversions through each step of calculation.",
        "role": "format",
        "scope": "operational",
        "stage": "mid",
        "tags": ["computation", "units"],
    },
]

COLDSTART_OPERATIONAL = [
    {
