        "stage": "late",
        "tags": ["completeness", "truncation"],
    },
    {
        "failure_pattern": "Answer omits required format elements (units, separators, labels)",
        "observable_symptom": "Final answer violates an explicit formatting directive",
        "preventive_check": "Re-read the global constraints immediately before emitting the final answer.",
        "role": "pitfall",
        "scope": "operational",
        "stage": "late",
        "tags": ["format", "constraints"],
    },
]


class PraxisAnchorMemoryProvider(BaseMemoryProvider):
    """Contract-anchored, reliability-calibrated memory provider."""

    ROLES = [
        "planning",
        "coverage",
        "fidelity",
        "format",
        "tool_usage",
        "error_handling",
        "pitfall",
    ]
    STAGES = ["begin", "mid", "late"]
    SCOPES = ["task_family", "operational"]

    def __init__(self, config: Optional[Dict[str, Any]] = None):
        super().__init__(
            memory_type=MemoryType.PRAXIS_ANCHOR_MEMORY,
            config=config or {},
        )
        self.config = config or {}

        # Logger
        self.logger = logging.getLogger(f"{__name__}.PraxisAnchor")
        if not self.logger.handlers:
            handler = logging.StreamHandler()
            formatter = logging.Formatter(
                "[%(asctime)s] [PraxisAnchor] [%(levelname)s] %(message)s"
            )
            handler.setFormatter(formatter)
            self.logger.addHandler(handler)
            self.logger.setLevel(logging.INFO)

        self.model = self.config.get("model", None)

        # Storage
        self.storage_dir = self.config.get(
            "storage_dir", "./storage/praxis_anchor_memory"
        )
        os.makedirs(self.storage_dir, exist_ok=True)

        self.ledger_path = self.config.get(
            "ledger_path", os.path.join(self.storage_dir, "ledger.json")
        )
        self.snapshot_path = self.config.get(
            "snapshot_path", os.path.join(self.storage_dir, "task_snapshots.json")
        )

        # Parameters
        self.max_total_items = int(self.config.get("max_total_items", 80))
        self.max_per_bucket = int(self.config.get("max_per_bucket", 40))
        self.top_k_longterm = int(self.config.get("top_k_longterm", 6))
        self.shortterm_interval = int(self.config.get("shortterm_interval", 2))
        self.max_shortterm_items = int(self.config.get("max_shortterm_items", 12))
        self.exploration_quota = int(self.config.get("exploration_quota", 2))
        self.near_dup_jaccard = float(self.config.get("near_dup_jaccard", 0.62))
        self.enable_longterm_provision = bool(
            self.config.get("enable_longterm_provision", True)
        )
        self.recency_half_life_tasks = float(
            self.config.get("recency_half_life_tasks", 10.0)
        )

        # In-memory runtime
        self._lock = threading.RLock()
        self._task_counter = 0
        self._memory_counter = 0

        # Current task context (single active task assumed, but snapshots allow recovery)
        self.task_context: Dict[str, Any] = {}

        # Task snapshots: task_id -> {query_signature, used_memory_ids, begin_time, closed}
        self._task_snapshots: Dict[str, Dict[str, Any]] = {}
        # Query signature -> task_id for ingestion fallback
        self._query_to_task_id: Dict[str, str] = {}

        # Ledger loaded in initialize()
        self.ledger: Dict[str, Any] = {}

        self._reset_task_context()

    # ------------------------------------------------------------------
    # Lifecycle
    # ------------------------------------------------------------------

    def initialize(self) -> bool:
        try:
            self.logger.info("Initializing Praxis Anchor Memory System")
            self.ledger = self._load_ledger()
            self._load_snapshots()
            self.logger.info(
                "Ledger loaded: %d strategic, %d operational, %d pitfalls",
                len(self.ledger.get("strategic", [])),
                len(self.ledger.get("operational", [])),
                len(self.ledger.get("pitfalls", [])),
            )
            return True
        except Exception as e:
            self.logger.error("Initialization failed: %s", e, exc_info=True)
            return False

    def _reset_task_context(self) -> None:
        self.task_context = {
            "task_id": None,
            "query": None,
            "start_time": None,
            "current_step": 0,
            "last_shortterm_provision_step": -999,
            "longterm_provided": False,
            "last_context": "",
            "agent_steps": [],
            "used_memory_ids": [],
            "contract": None,
            "contract_status": None,
            "shortterm_memory": [],
        }

    # ------------------------------------------------------------------
    # PROVIDE
    # ------------------------------------------------------------------

    def provide_memory(self, request: MemoryRequest) -> MemoryResponse:
        if not self.ledger:
            self.initialize()

        self.logger.info("=" * 70)
        self.logger.info(
            "PROVIDE | phase=%s | query=%.120s", request.status.value, request.query
        )

        try:
            if request.status == MemoryStatus.BEGIN:
                # New task detection
                if (
                    self.task_context.get("query") is None
                    or self.task_context.get("query") != request.query
                ):
                    self._start_new_task(request.query)

                self._increment_step()
                self._handle_begin(request)
            elif request.status == MemoryStatus.IN:
                self._increment_step()
                self._handle_in(request)

            memories = self._assemble_memories()
            self.logger.info("Returning %d memory item(s)", len(memories))
            return MemoryResponse(
                memories=memories,
                memory_type=MemoryType.PRAXIS_ANCHOR_MEMORY,
                total_count=len(memories),
            )
        except Exception as e:
            self.logger.error("provide_memory error: %s", e, exc_info=True)
            return MemoryResponse(
                memories=[],
                memory_type=MemoryType.PRAXIS_ANCHOR_MEMORY,
                total_count=0,
            )

    def _start_new_task(self, query: str) -> None:
        with self._lock:
            self._task_counter += 1
            task_id = f"task_{int(time.time() * 1000)}_{self._task_counter}"
            self._reset_task_context()
            self.task_context["task_id"] = task_id
            self.task_context["query"] = query
            self.task_context["start_time"] = time.time()

            query_sig = self._signature(query)
            self._task_snapshots[task_id] = {
                "query_signature": query_sig,
                "query_preview": query[:120],
                "used_memory_ids": [],
                "begin_time": time.time(),
                "closed": False,
            }
            self._query_to_task_id[query_sig] = task_id
            self._save_snapshots()
            self.logger.info("New task started: %s", task_id)

    def _increment_step(self) -> None:
        self.task_context["current_step"] = (
            self.task_context.get("current_step", 0) + 1
        )

    def _handle_begin(self, request: MemoryRequest) -> None:
        # 1. Decompose deliverable contract
        contract = self._decompose_contract(request.query)
        self.task_context["contract"] = contract
        self.task_context["contract_status"] = self._initial_contract_status(contract)

        # 2. Retrieve long-term guidance (if enabled)
        if self.enable_longterm_provision and not self.task_context.get(
            "longterm_provided"
        ):
            guidance = self._retrieve_longterm_memory(request)
            if guidance:
                self.task_context["shortterm_memory"].append(
                    {"kind": "longterm_guidance", "content": guidance}
                )
                self.task_context["longterm_provided"] = True

        # 3. Auto-extract short-term items from BEGIN context
        self._auto_extract_shortterm(request)

    def _handle_in(self, request: MemoryRequest) -> None:
        # Extract new information from the current step
        self._auto_extract_shortterm(request)

        # Re-derive contract status from accumulated step summaries
        contract = self.task_context.get("contract")
        if contract and self.task_context.get("agent_steps"):
            self.task_context["contract_status"] = self._update_contract_status(
                contract, self.task_context["agent_steps"]
            )

        # Interval-gated short-term provision
        last = self.task_context.get("last_shortterm_provision_step", -999)
        current = self.task_context.get("current_step", 0)
        if current - last >= self.shortterm_interval:
            self.task_context["last_shortterm_provision_step"] = current
            self.task_context["shortterm_provision_pending"] = True
        else:
            self.task_context["shortterm_provision_pending"] = False

    def _assemble_memories(self) -> List[MemoryItem]:
        memories = []

        # Contract status (provided at BEGIN and on interval during IN)
        contract_status = self.task_context.get("contract_status")
        if contract_status and (
            self.task_context.get("current_step") == 1
            or self.task_context.get("shortterm_provision_pending")
        ):
            memories.append(self._make_text_item(
                "contract_status",
                self._render_contract_status(contract_status),
                phase="begin" if self.task_context.get("current_step") == 1 else "in",
            ))

        # Short-term / long-term guidance
        if self.task_context.get("current_step") == 1 or self.task_context.get(
            "shortterm_provision_pending"
        ):
            content = self._render_shortterm_memory()
            if content:
                memories.append(
                    self._make_text_item(
                        "shortterm_guidance",
                        content,
                        phase="begin" if self.task_context.get("current_step") == 1 else "in",
                    )
                )

        return memories

    def _make_text_item(self, kind: str, content: str, phase: str) -> MemoryItem:
        self._memory_counter += 1
        return MemoryItem(
            id=f"praxis_{kind}_{self._memory_counter}",
            content=content,
            metadata={"source": "praxis_anchor", "kind": kind, "phase": phase},
            type=MemoryItemType.TEXT,
        )

    # ------------------------------------------------------------------
    # Deliverable contract
    # ------------------------------------------------------------------

    def _decompose_contract(self, query: str) -> Dict[str, Any]:
        if not self.model:
            return self._fallback_contract(query)

        prompt = f"""You are a planning assistant. Decompose the task into a checkable deliverable contract.

Task:
{query}

Return JSON with:
{{
  "deliverables": [
    {{
      "name": "short name",
      "min_extent": "e.g. >=5000 words, 6 chapters, 5 cases, or null if unspecified",
      "required_elements": ["element1", "element2"],
      "format_rules": ["rule1", "rule2"]
    }}
  ],
  "global_constraints": ["constraint1", "constraint2"],
  "completion_criteria": ["criterion1", "criterion2"]
}}

Only include constraints that are explicitly stated or strongly implied by the task. If no explicit contract exists, derive a minimal reasonable one.
Output JSON only."""

        resp = self._call_llm(prompt)
        parsed = self._parse_json(resp)
        if isinstance(parsed, dict) and "deliverables" in parsed:
            return parsed
        return self._fallback_contract(query)

    def _fallback_contract(self, query: str) -> Dict[str, Any]:
        # Minimal non-hardcoded fallback: a single deliverable derived from the query
        return {
            "deliverables": [
                {
                    "name": "primary answer",
                    "min_extent": None,
                    "required_elements": ["complete answer to the query"],
                    "format_rules": [],
                }
            ],
            "global_constraints": [],
            "completion_criteria": ["address the task comprehensively"],
        }

    def _initial_contract_status(self, contract: Dict[str, Any]) -> Dict[str, Any]:
        deliverables = contract.get("deliverables", [])
        return {
            "deliverables": [
                {"name": d.get("name", f"item_{i}"), "status": "unmet"}
                for i, d in enumerate(deliverables)
            ],
            "global_constraints": [
                {"constraint": c, "status": "unmet"}
                for c in contract.get("global_constraints", [])
            ],
            "overall": "in_progress",
        }

    def _update_contract_status(
        self, contract: Dict[str, Any], agent_steps: List[Dict[str, Any]]
    ) -> Dict[str, Any]:
        if not self.model:
            return self.task_context.get("contract_status") or self._initial_contract_status(contract)

        steps_text = "\n".join(
            f"Step {s['step']}: {s['summary']}" for s in agent_steps[-8:]
        )
        deliverables = contract.get("deliverables", [])
        constraints = contract.get("global_constraints", [])

        prompt = f"""You are tracking task completion against a contract.

Contract deliverables:
{json.dumps(deliverables, indent=2)}

Global constraints:
{json.dumps(constraints, indent=2)}

Recent execution steps:
{steps_text}

For each deliverable and constraint, infer status: "unmet", "in_progress", or "done".
Return JSON:
{{
  "deliverables": [{{"name": "...", "status": "..."}}],
  "global_constraints": [{{"constraint": "...", "status": "..."}}],
  "overall": "unmet|in_progress|done"
}}
Only mark "done" when the steps provide clear evidence. Output JSON only."""

        resp = self._call_llm(prompt)
        parsed = self._parse_json(resp)
        if isinstance(parsed, dict) and "deliverables" in parsed:
            return parsed
        return self.task_context.get("contract_status") or self._initial_contract_status(contract)

    def _render_contract_status(self, status: Dict[str, Any]) -> str:
        lines = ["**Deliverable Contract Status:**"]
        for d in status.get("deliverables", []):
            mark = {"done": "✓", "in_progress": "→", "unmet": "✗"}.get(
                d.get("status"), "?"
            )
            lines.append(f"- [{mark}] {d.get('name')}: {d.get('status')}")
        for c in status.get("global_constraints", []):
            mark = {"done": "✓", "in_progress": "→", "unmet": "✗"}.get(
                c.get("status"), "?"
            )
            lines.append(f"- [{mark}] {c.get('constraint')}: {c.get('status')}")
        lines.append(f"**Overall:** {status.get('overall', 'unknown')}")
        return "\n".join(lines)

    # ------------------------------------------------------------------
    # Auto-extraction (short-term memory)
    # ------------------------------------------------------------------

    def _auto_extract_shortterm(self, request: MemoryRequest) -> None:
        if not self.model:
            return

        delta = self._context_delta(request.context)
        self.task_context["last_context"] = request.context

        if len(delta.strip()) < 40:
            return

        current = "\n".join(
            f"- {item['content']}" for item in self.task_context.get("shortterm_memory", [])
            if item.get("kind") != "longterm_guidance"
        ) or "(none)"
        prev_steps = "\n".join(
            f"Step {s['step']}: {s['summary']}"
            for s in self.task_context.get("agent_steps", [])[-6:]
        ) or "(none)"

        prompt = f"""Analyze this execution step. Perform two tasks:

1. Summarize what the agent did in 2-3 sentences.
2. Extract task-relevant key information (max 3 items) that should be remembered.

Original task:
{request.query}

Previous steps:
{prev_steps}

Already remembered:
{current}

New information from this step:
{delta}

Return JSON:
{{
  "step_summary": "...",
  "key_extracts": ["...", "..."]
}}

Extraction rules:
- EXTRACT: task constraints, key data values, important discoveries, format requirements directly related to task content.
- DO NOT EXTRACT: system instructions, tool usage specs, memory-system guidance, general workflow rules.
- Each extract: one concise sentence, prefer direct quotes or close paraphrases.
- If nothing new/important, return empty array.

JSON only."""

        resp = self._call_llm(prompt)
        parsed = self._parse_json(resp)
        if not isinstance(parsed, dict):
            return

        summary = str(parsed.get("step_summary", "")).strip()
        if summary:
            self.task_context["agent_steps"].append(
                {
                    "step": self.task_context.get("current_step", 0),
                    "summary": summary,
                    "phase": request.status.value,
                }
            )

        for item in parsed.get("key_extracts", []):
            item = str(item).strip()
            if item and len(item) > 10:
                self._add_shortterm_item(item)

    def _add_shortterm_item(self, item: str) -> None:
        mem = self.task_context.setdefault("shortterm_memory", [])
        # Deduplicate exact
        for existing in mem:
            if existing.get("content") == item:
                return
        mem.append({"kind": "extract", "content": item})
        # Trim by recency if too many
        if len(mem) > self.max_shortterm_items:
            # Keep longterm guidance and most recent items
            guidance = [m for m in mem if m.get("kind") == "longterm_guidance"]
            extracts = [m for m in mem if m.get("kind") == "extract"]
            extracts = extracts[-(self.max_shortterm_items - len(guidance)):]
            self.task_context["shortterm_memory"] = guidance + extracts

    def _context_delta(self, current: str) -> str:
        last = self.task_context.get("last_context", "")
        if not last:
            return current.strip()
        if current.startswith(last):
            return current[len(last):].strip()
        return current.strip()

    def _render_shortterm_memory(self) -> str:
        mem = self.task_context.get("shortterm_memory", [])
        if not mem:
            return ""
        lines = ["**Key Information & Constraints:**"]
        for i, item in enumerate(mem, 1):
            kind = item.get("kind")
            prefix = "Guidance: " if kind == "longterm_guidance" else ""
            lines.append(f"{i}. {prefix}{item['content']}")
        return "\n".join(lines)

    # ------------------------------------------------------------------
    # Long-term retrieval (BEGIN)
    # ------------------------------------------------------------------

    def _retrieve_longterm_memory(self, request: MemoryRequest) -> Optional[str]:
        if not self.model or not self.ledger:
            return None

        candidates = self._collect_candidates()
        if not candidates:
            return None

        # Pre-filter by utility to cap prompt size
        ranked = sorted(
            candidates,
            key=lambda c: self._utility_score(c),
            reverse=True,
        )[:24]

        # Exploration: force-include untested low-exposure memories
        exploration = self._select_exploration_candidates(ranked)
        selected_candidates = {c["id"]: c for c in ranked}
        for e in exploration:
            selected_candidates[e["id"]] = e
        final_candidates = list(selected_candidates.values())

        guidance = self._synthesize_guidance(request.query, final_candidates, exploration)
        if not guidance:
            return None

        # Mark exposure
        for c in final_candidates:
            self._mark_exposed(c["id"])

        return guidance

    def _collect_candidates(self) -> List[Dict[str, Any]]:
        cands = []
        for bucket in ("strategic", "operational", "pitfalls"):
            for item in self.ledger.get(bucket, []):
                c = dict(item)
                c["bucket"] = bucket
                c["evidence_label"] = self._evidence_label(item)
                c["reliability"] = self._smoothed_reliability(item)
                c["utility"] = self._utility_score(c)
                cands.append(c)
        return cands

    def _select_exploration_candidates(
        self, ranked: List[Dict[str, Any]]
    ) -> List[Dict[str, Any]]:
        if self.exploration_quota <= 0:
            return []
        # Anneal quota by coverage: if most memories have been exposed, reduce
        total = len(ranked)
        if total == 0:
            return []
        exposed = sum(1 for c in ranked if c.get("exposed_count", 0) > 0)
        coverage = exposed / total
        quota = max(0, int(round(self.exploration_quota * (1.0 - coverage))))
        if quota == 0:
            return []
        untested = [
            c for c in ranked
            if c.get("exposed_count", 0) < 2 and c.get("status", "provisional") != "retired"
        ]
        untested.sort(key=lambda c: c.get("exposed_count", 0))
        return untested[:quota]

    def _synthesize_guidance(
        self,
        query: str,
        candidates: List[Dict[str, Any]],
        exploration: List[Dict[str, Any]],
    ) -> str:
        lines = []
        for i, c in enumerate(candidates, 1):
            role = c.get("role", "unknown")
            label = c.get("evidence_label", "untested")
            content = c.get("content") or c.get("preventive_check") or ""
            if c.get("bucket") == "pitfalls":
                content = (
                    f"Pitfall: {c.get('failure_pattern')} → symptom: {c.get('observable_symptom')} "
                    f"→ check: {c.get('preventive_check')}"
                )
            lines.append(
                f"{i}. [{role.upper()}] [{label}] {content}"
            )

        prompt = f"""You are a memory guidance system. Select and synthesize the most relevant memories for this task.

Task:
{query}

Available memories:
{chr(10).join(lines)}

Selection rules:
1. Select the top {self.top_k_longterm} most relevant items.
2. Ensure at least one planning/coverage item and at least one pitfall are included if available.
3. Items labelled "untested" are exploratory; include at most 2 unless clearly irrelevant.
4. Synthesize into concise, actionable guidance (4-6 sentences, bullet points allowed).
5. Frame as suggestions: "Consider...", "Based on similar tasks...", "You might want to...".

Return JSON:
{{
  "selected_indices": [1, 3, 5],
  "guidance": "..."
}}

JSON only."""

        resp = self._call_llm(prompt)
        parsed = self._parse_json(resp)
        if isinstance(parsed, dict):
            indices = parsed.get("selected_indices", [])
            guidance = str(parsed.get("guidance", "")).strip()
            # Record used IDs for selected
            for idx in indices:
                if isinstance(idx, int) and 1 <= idx <= len(candidates):
                    c = candidates[idx - 1]
                    if c["id"] not in self.task_context["used_memory_ids"]:
                        self.task_context["used_memory_ids"].append(c["id"])
            # Also record exploration items even if not selected (they were exposed)
            for e in exploration:
                if e["id"] not in self.task_context["used_memory_ids"]:
                    self.task_context["used_memory_ids"].append(e["id"])
            # Persist snapshot
            self._persist_used_ids()
            return guidance

        # Fallback: return top-3 verbatim
        fallback = "\n".join(
            f"- {c.get('content') or c.get('preventive_check')}"
            for c in candidates[:3]
        )
        for c in candidates[:3]:
            if c["id"] not in self.task_context["used_memory_ids"]:
                self.task_context["used_memory_ids"].append(c["id"])
        self._persist_used_ids()
        return fallback

    def _mark_exposed(self, memory_id: str) -> None:
        with self._lock:
            for bucket in ("strategic", "operational", "pitfalls"):
                for item in self.ledger.get(bucket, []):
                    if item["id"] == memory_id:
                        item["exposed_count"] = item.get("exposed_count", 0) + 1
                        item["last_used_at"] = time.time()
                        return

    def _persist_used_ids(self) -> None:
        tid = self.task_context.get("task_id")
        if tid and tid in self._task_snapshots:
            self._task_snapshots[tid]["used_memory_ids"] = list(
                self.task_context.get("used_memory_ids", [])
            )
            self._save_snapshots()

    # ------------------------------------------------------------------
    # INGEST
    # ------------------------------------------------------------------

    def take_in_memory(self, trajectory_data: TrajectoryData) -> Tuple[bool, str]:
        if not self.ledger:
            self.initialize()

        self.logger.info("INGEST | query=%.120s", trajectory_data.query)

        try:
            metadata = trajectory_data.metadata or {}
            task_id = self._resolve_task_id(trajectory_data)

            is_success = self._is_success(metadata)

            if is_success:
                # Attribution check before extraction
                self._attribution_check(trajectory_data, task_id)
                extracted = self._extract_success_memories(trajectory_data)
                self._ingest_items(extracted, trajectory_data, task_id)
            else:
                pitfalls = self._extract_pitfalls(trajectory_data)
                self._ingest_items(pitfalls, trajectory_data, task_id, is_pitfall=True)

            # Record success/failure for used memories (coarse fallback)
            if is_success:
                self._mark_followed_by_success(task_id)

            # Lifecycle curation
            self._curate_ledger()

            # Persist
            self._save_ledger()
            self._close_task(task_id)

            return True, "Praxis Anchor ingestion complete"
        except Exception as e:
            self.logger.error("take_in_memory error: %s", e, exc_info=True)
            return False, f"Ingestion failed: {e}"

    def _resolve_task_id(self, trajectory_data: TrajectoryData) -> str:
        metadata = trajectory_data.metadata or {}
        # 1. Explicit task_id
        tid = metadata.get("task_id")
        if tid and tid in self._task_snapshots:
            return tid
        # 2. Match by query signature
        qs = self._signature(trajectory_data.query)
        tid = self._query_to_task_id.get(qs)
        if tid and tid in self._task_snapshots:
            return tid
        # 3. Most recent unclosed snapshot
        unclosed = [
            (tid, s)
            for tid, s in self._task_snapshots.items()
            if not s.get("closed")
        ]
        if unclosed:
            unclosed.sort(key=lambda x: x[1].get("begin_time", 0), reverse=True)
            return unclosed[0][0]
        # 4. Mint new
        self._task_counter += 1
        tid = f"task_ingest_{int(time.time() * 1000)}_{self._task_counter}"
        self._task_snapshots[tid] = {
            "query_signature": qs,
            "query_preview": trajectory_data.query[:120],
            "used_memory_ids": [],
            "begin_time": time.time(),
            "closed": False,
        }
        self._query_to_task_id[qs] = tid
        self._save_snapshots()
        return tid

    def _attribution_check(
        self, trajectory_data: TrajectoryData, task_id: str
    ) -> None:
        if not self.model:
            return
        used = self._task_snapshots.get(task_id, {}).get("used_memory_ids", [])
        if not used:
            return

        # Build a compact memory list
        mem_descriptions = []
        for mid in used:
            item = self._find_by_id(mid)
            if item:
                mem_descriptions.append(
                    {
                        "id": mid,
                        "content": item.get("content")
                        or item.get("preventive_check")
                        or "",
                    }
                )
        if not mem_descriptions:
            return

        traj_summary = self._trajectory_summary(trajectory_data)
        prompt = f"""Determine whether each injected memory was actually followed in the trajectory.

Injected memories:
{json.dumps(mem_descriptions, indent=2)}

Trajectory summary:
{traj_summary}

For each memory id, decide if its guidance was REFLECTED in the agent's actions or output (not merely exposed).
Return JSON: {{"followed": ["id1", "id2"], "not_followed": ["id3"]}}
JSON only."""

        resp = self._call_llm(prompt)
        parsed = self._parse_json(resp)
        if isinstance(parsed, dict):
            followed = parsed.get("followed", [])
            for mid in followed:
                self._mark_followed(mid)

    def _mark_followed(self, memory_id: str) -> None:
        with self._lock:
            for bucket in ("strategic", "operational", "pitfalls"):
                for item in self.ledger.get(bucket, []):
                    if item["id"] == memory_id:
                        item["followed_count"] = item.get("followed_count", 0) + 1
                        item["usage_count"] = item.get("usage_count", 0) + 1
                        if item.get("status") == "provisional" and item["followed_count"] >= 2:
                            item["status"] = "established"
                        return

    def _mark_followed_by_success(self, task_id: str) -> None:
        """Coarse fallback: if no attribution check ran, count used as followed."""
        used = self._task_snapshots.get(task_id, {}).get("used_memory_ids", [])
        for mid in used:
            item = self._find_by_id(mid)
            if item and item.get("followed_count", 0) == 0:
                # Only bump if not already attributed
                item["followed_count"] = item.get("followed_count", 0) + 1
                item["usage_count"] = item.get("usage_count", 0) + 1

    def _extract_success_memories(
        self, trajectory_data: TrajectoryData
    ) -> List[Dict[str, Any]]:
        if not self.model:
            return []

        metadata = trajectory_data.metadata or {}
        # Gap-directed: include dimension scores/reasons if present
        grades = metadata.get("grades") or metadata.get("dimension_scores") or {}
        grade_text = ""
        if isinstance(grades, dict) and grades:
            grade_text = "\n**Performance gaps (use to target extraction):**\n" + "\n".join(
                f"- {k}: {v}" for k, v in grades.items()
            )

        orientation = self.config.get("philo_orientation_items", [])
        orientation_text = ""
        if orientation:
            orientation_text = (
                "\n**Current revisable working principles (criteria, not task facts):**\n"
                + "\n".join(f"- {p}" for p in orientation)
                + "\nUse these as provisional criteria. Do not copy them as learned facts; ground each insight in the trajectory.\n"
            )

        traj_str = json.dumps(trajectory_data.trajectory or [], ensure_ascii=False)[:12000]
        prompt = f"""Extract reusable learnings from this successful execution.

Task:
{trajectory_data.query}

Trajectory (truncated):
{traj_str}

Result:
{str(trajectory_data.result)[:2000]}
{grade_text}
{orientation_text}

Extract at most 4 items total. For each item provide:
- content: 1-2 sentences, reusable pattern (not task-specific data)
- role: one of {self.ROLES}
- scope: one of {self.SCOPES}
- stage: one of {self.STAGES}
- abstraction: "principle" (task-family strategy) or "technique" (operational)
- evidence_span: short quote or step reference from trajectory

Focus on gaps if performance grades are provided; otherwise focus on transferable insights.

Return JSON:
{{"items": [
  {{"content": "...", "role": "...", "scope": "...", "stage": "...", "abstraction": "...", "evidence_span": "..."}}
]}}
JSON only."""

        resp = self._call_llm(prompt)
        parsed = self._parse_json(resp)
        items = []
        if isinstance(parsed, dict) and isinstance(parsed.get("items"), list):
            for raw in parsed["items"]:
                if isinstance(raw, dict) and raw.get("content"):
                    item = dict(raw)
                    item.setdefault("role", "coverage")
                    item.setdefault("scope", "task_family")
                    item.setdefault("stage", "mid")
                    items.append(item)
        return items

    def _extract_pitfalls(
        self, trajectory_data: TrajectoryData
    ) -> List[Dict[str, Any]]:
        if not self.model:
            return []

        metadata = trajectory_data.metadata or {}
        grades = metadata.get("grades") or metadata.get("dimension_scores") or {}
        grade_text = ""
        if isinstance(grades, dict) and grades:
            grade_text = "\n**Low dimension reasons:**\n" + "\n".join(
                f"- {k}: {v}" for k, v in grades.items()
            )

        traj_str = json.dumps(trajectory_data.trajectory or [], ensure_ascii=False)[:12000]
        prompt = f"""Diagnose the failure in this execution and extract preventive checks.

Task:
{trajectory_data.query}

Trajectory (truncated):
{traj_str}

Result:
{str(trajectory_data.result)[:2000]}
{grade_text}

Extract at most 2 pitfall items. Each item:
- failure_pattern: concise description of what went wrong
- observable_symptom: how it manifests in the output/trajectory
- preventive_check: concrete check to perform before finalising next time
- scope: one of {self.SCOPES}
- stage: one of {self.STAGES}

Return JSON:
{{"items": [
  {{"failure_pattern": "...", "observable_symptom": "...", "preventive_check": "...", "scope": "...", "stage": "..."}}
]}}
JSON only."""

        resp = self._call_llm(prompt)
        parsed = self._parse_json(resp)
        items = []
        if isinstance(parsed, dict) and isinstance(parsed.get("items"), list):
            for raw in parsed["items"]:
                if isinstance(raw, dict) and raw.get("failure_pattern"):
                    item = dict(raw)
                    item["role"] = "pitfall"
                    item.setdefault("scope", "task_family")
                    item.setdefault("stage", "late")
                    items.append(item)
        return items

    def _ingest_items(
        self,
        items: List[Dict[str, Any]],
        trajectory_data: TrajectoryData,
        task_id: str,
        is_pitfall: bool = False,
    ) -> None:
        for raw in items:
            content = (
                raw.get("content")
                or raw.get("preventive_check")
                or raw.get("failure_pattern", "")
            ).strip()
            if len(content) < 15:
                continue

            # Near-duplicate merge
            merged = self._try_merge_near_duplicate(raw, is_pitfall)
            if merged:
                continue

            self._memory_counter += 1
            memory_id = f"praxis_{int(time.time() * 1000)}_{self._memory_counter}"
            bucket = "pitfalls" if is_pitfall else (
                "operational" if raw.get("abstraction") == "technique" else "strategic"
            )

            entry = {
                "id": memory_id,
                "content": content,
                "role": raw.get("role", "coverage"),
                "scope": raw.get("scope", "task_family"),
                "stage": raw.get("stage", "mid"),
                "tags": raw.get("tags", []),
                "created_at": time.time(),
                "last_used_at": None,
                "exposed_count": 0,
                "followed_count": 0,
                "usage_count": 0,
                "success_count": 0,
                "status": "provisional",
                "source_task": trajectory_data.query[:150],
                "evidence_span": raw.get("evidence_span", ""),
                "signature": self._signature(content.lower()),
            }
            if is_pitfall:
                entry.update(
                    {
                        "failure_pattern": raw.get("failure_pattern", ""),
                        "observable_symptom": raw.get("observable_symptom", ""),
                        "preventive_check": raw.get("preventive_check", ""),
                    }
                )

            self.ledger.setdefault(bucket, []).append(entry)
            self.logger.info("Ingested %s item: %.80s", bucket, content)

    def _try_merge_near_duplicate(
        self, raw: Dict[str, Any], is_pitfall: bool
    ) -> bool:
        candidates_text = (
            raw.get("content")
            or raw.get("preventive_check")
            or raw.get("failure_pattern", "")
        ).strip()
        if not candidates_text:
            return False

        bucket = "pitfalls" if is_pitfall else "strategic"
        for bucket_name in ("strategic", "operational", "pitfalls"):
            for existing in self.ledger.get(bucket_name, []):
                existing_text = (
                    existing.get("content")
                    or existing.get("preventive_check")
                    or existing.get("failure_pattern", "")
                )
                sim = self._jaccard(candidates_text, existing_text)
                if sim >= self.near_dup_jaccard:
                    if self._llm_confirm_merge(candidates_text, existing_text):
                        # Merge: keep existing, carry forward origin info
                        self.logger.info(
                            "Merged near-duplicate: %.60s", candidates_text
                        )
                        existing["created_at"] = min(
                            existing.get("created_at", time.time()),
                            time.time(),
                        )
                        return True
        return False

    def _llm_confirm_merge(self, a: str, b: str) -> bool:
        if not self.model:
            return True
        prompt = f"""Do these two memory items express the same reusable insight (such that one is redundant)?
A: {a}
B: {b}
Return JSON: {{"merge": true/false, "reason": "..."}} JSON only."""
        resp = self._call_llm(prompt)
        parsed = self._parse_json(resp)
        if isinstance(parsed, dict):
            return bool(parsed.get("merge", False))
        return False

    # ------------------------------------------------------------------
    # Lifecycle / curation
    # ------------------------------------------------------------------

    def _curate_ledger(self) -> None:
        with self._lock:
            total = sum(
                len(self.ledger.get(b, []))
                for b in ("strategic", "operational", "pitfalls")
            )
            if total <= self.max_total_items:
                return

            all_items = []
            for bucket in ("strategic", "operational", "pitfalls"):
                for item in self.ledger.get(bucket, []):
                    all_items.append((bucket, item))

            # Protect new items (created < 3 tasks ago) and pitfalls for first 2 exposures
            now = time.time()
            def utility(pair):
                bucket, item = pair
                base = self._utility_score(item)
                age_days = (now - item.get("created_at", now)) / 86400.0
                if age_days < 2.0:
                    base *= 1.5  # grace period
                if item.get("role") == "pitfall" and item.get("exposed_count", 0) < 2:
                    base *= 1.3
                return base

            all_items.sort(key=utility, reverse=True)
            keep = all_items[: self.max_total_items]
            drop = all_items[self.max_total_items:]

            # Rebuild buckets
            new_ledger = {"strategic": [], "operational": [], "pitfalls": [], "meta": self.ledger.get("meta", {})}
            for bucket, item in keep:
                new_ledger[bucket].append(item)
            self.ledger = new_ledger
            self.logger.info("Curated ledger: dropped %d low-utility items", len(drop))

    def _utility_score(self, item: Dict[str, Any]) -> float:
        rel = self._smoothed_reliability(item)
        exposures = item.get("exposed_count", 0)
        # Recency decay based on task count is approximated with last_used_at
        last = item.get("last_used_at") or item.get("created_at") or time.time()
        age_days = max(0.0, (time.time() - last) / 86400.0)
        recency = 0.5 ** (age_days / max(self.recency_half_life_tasks, 1e-6))
        role_weight = {
            "planning": 1.1,
            "coverage": 1.2,
            "fidelity": 1.1,
            "format": 1.0,
            "tool_usage": 1.0,
            "error_handling": 1.05,
            "pitfall": 1.3,
        }.get(item.get("role", "coverage"), 1.0)
        # New items get a boost to survive early pruning
        if item.get("status") == "provisional":
            role_weight *= 1.2
        return (0.2 + rel) * recency * role_weight * (1.0 + 0.05 * min(exposures, 10))

    # ------------------------------------------------------------------
    # Reliability helpers
    # ------------------------------------------------------------------

    def _smoothed_reliability(self, item: Dict[str, Any]) -> float:
        followed = item.get("followed_count", 0)
        exposed = item.get("exposed_count", 0)
        return (followed + 1.0) / (exposed + 2.0)

    def _evidence_label(self, item: Dict[str, Any]) -> str:
        exposed = item.get("exposed_count", 0)
        if exposed == 0:
            return "untested"
        if exposed < 3:
            return "few samples"
        return "established"

    # ------------------------------------------------------------------
    # Persistence
    # ------------------------------------------------------------------

    def _load_ledger(self) -> Dict[str, Any]:
        if os.path.exists(self.ledger_path):
            try:
                with open(self.ledger_path, "r", encoding="utf-8") as f:
                    data = json.load(f)
                if self._is_valid_ledger(data):
                    return data
            except Exception as e:
                self.logger.warning("Ledger load failed: %s", e)

        # Cold start
        ledger = {"strategic": [], "operational": [], "pitfalls": [], "meta": {"version": 2}}
        for raw in COLDSTART_STRATEGIC:
            ledger["strategic"].append(self._coldstart_entry(raw))
        for raw in COLDSTART_OPERATIONAL:
            ledger["operational"].append(self._coldstart_entry(raw))
        for raw in COLDSTART_PITFALLS:
            entry = self._coldstart_entry(raw)
            entry.update(
                {
                    "failure_pattern": raw["failure_pattern"],
                    "observable_symptom": raw["observable_symptom"],
                    "preventive_check": raw["preventive_check"],
                }
            )
            ledger["pitfalls"].append(entry)
        self._save_ledger_data(ledger)
        return ledger

    def _coldstart_entry(self, raw: Dict[str, Any]) -> Dict[str, Any]:
        self._memory_counter += 1
        content = raw.get("content") or raw.get("preventive_check") or raw.get("failure_pattern", "")
        return {
            "id": f"praxis_coldstart_{self._memory_counter}",
            "content": content,
            "role": raw.get("role", "coverage"),
            "scope": raw.get("scope", "task_family"),
            "stage": raw.get("stage", "mid"),
            "tags": raw.get("tags", []),
            "created_at": time.time(),
            "last_used_at": None,
            "exposed_count": 0,
            "followed_count": 0,
            "usage_count": 0,
            "success_count": 0,
            "status": "provisional",
            "source_task": "cold_start",
            "evidence_span": "",
            "signature": self._signature(content.lower()),
        }

    def _is_valid_ledger(self, data: Any) -> bool:
        return (
            isinstance(data, dict)
            and all(isinstance(data.get(b), list) for b in ("strategic", "operational", "pitfalls"))
        )

    def _save_ledger(self) -> None:
        self._save_ledger_data(self.ledger)

    def _save_ledger_data(self, data: Dict[str, Any]) -> None:
        try:
            tmp = self.ledger_path + ".tmp"
            with open(tmp, "w", encoding="utf-8") as f:
                json.dump(data, f, ensure_ascii=False, indent=2)
            os.replace(tmp, self.ledger_path)
        except Exception as e:
            self.logger.error("Ledger save failed: %s", e)

    def _load_snapshots(self) -> None:
        if os.path.exists(self.snapshot_path):
            try:
                with open(self.snapshot_path, "r", encoding="utf-8") as f:
                    data = json.load(f)
                if isinstance(data, dict):
                    self._task_snapshots = data.get("task_snapshots", {})
                    self._query_to_task_id = data.get("query_to_task_id", {})
            except Exception as e:
                self.logger.warning("Snapshot load failed: %s", e)

    def _save_snapshots(self) -> None:
        try:
            tmp = self.snapshot_path + ".tmp"
            with open(tmp, "w", encoding="utf-8") as f:
                json.dump(
                    {
                        "task_snapshots": self._task_snapshots,
                        "query_to_task_id": self._query_to_task_id,
                    },
                    f,
                    ensure_ascii=False,
                    indent=2,
                )
            os.replace(tmp, self.snapshot_path)
        except Exception as e:
            self.logger.error("Snapshot save failed: %s", e)

    def _close_task(self, task_id: str) -> None:
        if task_id in self._task_snapshots:
            self._task_snapshots[task_id]["closed"] = True
            self._save_snapshots()

    # ------------------------------------------------------------------
    # Utilities
    # ------------------------------------------------------------------

    def _find_by_id(self, memory_id: str) -> Optional[Dict[str, Any]]:
        for bucket in ("strategic", "operational", "pitfalls"):
            for item in self.ledger.get(bucket, []):
                if item["id"] == memory_id:
                    return item
        return None

    def _is_success(self, metadata: Dict[str, Any]) -> bool:
        return (
            metadata.get("is_correct") is True
            or metadata.get("task_success") is True
            or metadata.get("outcome") == "success"
        )

    def _trajectory_summary(self, trajectory_data: TrajectoryData) -> str:
        traj = trajectory_data.trajectory or []
        lines = []
        for i, step in enumerate(traj[-10:], 1):
            if isinstance(step, dict):
                text = step.get("content") or step.get("text") or str(step)
                lines.append(f"{i}. {str(text)[:300]}")
            else:
                lines.append(f"{i}. {str(step)[:300]}")
        return "\n".join(lines) or "(empty)"

    def _jaccard(self, a: str, b: str) -> float:
        ta = set(re.findall(r"\w+", a.lower()))
        tb = set(re.findall(r"\w+", b.lower()))
        if not ta or not tb:
            return 0.0
        return len(ta & tb) / len(ta | tb)

    def _signature(self, text: str) -> str:
        return hashlib.sha256(text.encode("utf-8")).hexdigest()

    def _call_llm(self, prompt: str) -> str:
        if not self.model:
            return ""
        try:
            messages = [
                {"role": "user", "content": [{"type": "text", "text": prompt}]}
            ]
            response = self.model(messages)
            return getattr(response, "content", str(response)).strip()
        except Exception as e:
            self.logger.error("LLM call failed: %s", e)
            return ""

    def _parse_json(self, text: str) -> Optional[Any]:
        if not text:
            return None
        text = text.strip()
        try:
            return json.loads(text)
        except json.JSONDecodeError:
            pass
        for pattern in [r"```json\s*(.*?)```", r"```\s*(.*?)```"]:
            m = re.search(pattern, text, re.DOTALL)
            if m:
                try:
                    return json.loads(m.group(1).strip())
                except json.JSONDecodeError:
                    continue
        # Try to find object or array
        for pattern in [r"\{.*\}", r"\[.*\]"]:
            m = re.search(pattern, text, re.DOTALL)
            if m:
                try:
                    return json.loads(m.group(0))
                except json.JSONDecodeError:
                    continue
        return None

