class PraxisAnchorMemoryProvider(BaseMemoryProvider):
    """Contract-anchored, reliability-calibrated memory provider."""

    ROLES = [
        "planning",
        "coverage",
        "fidelity",
        "format",
        "tool_usage",
        "error_handling",
        "pitfall",
    ]
    STAGES = ["begin", "mid", "late"]
    SCOPES = ["task_family", "operational"]

    def __init__(self, config: Optional[Dict[str, Any]] = None):
        super().__init__(
            memory_type=MemoryType.PRAXIS_ANCHOR_MEMORY,
            config=config or {},
        )
        self.config = config or {}

        # Logger
        self.logger = logging.getLogger(f"{__name__}.PraxisAnchor")
        if not self.logger.handlers:
            handler = logging.StreamHandler()
            formatter = logging.Formatter(
                "[%(asctime)s] [PraxisAnchor] [%(levelname)s] %(message)s"
            )
            handler.setFormatter(formatter)
            self.logger.addHandler(handler)
            self.logger.setLevel(logging.INFO)

